#include "lock_manager.hpp"
#include "edudb.hpp"
#include <chrono>
#include <future>
#include <iostream>
#include <limits>
#include <random>
#include <thread>
using namespace edudb;using namespace std::chrono_literals;
namespace {
using Range=LockManager::IntegerRange;using Mode=LockMode;
std::size_t checks=0; nlohmann::json observations=nlohmann::json::array();
void need(bool b,const std::string& why){++checks;if(!b)throw std::runtime_error(why);}
template<class F>void error(const std::string& code,F f){try{f();}catch(const DbError& e){need(e.code==code,"Expected "+code+", got "+e.code);return;}throw std::runtime_error("Missing "+code);}
Range point(std::int64_t k){return {k,k,true,true};}
template<class F>void until(F f,const std::string& why){auto end=std::chrono::steady_clock::now()+1500ms;while(std::chrono::steady_clock::now()<end){if(f())return;std::this_thread::sleep_for(1ms);}throw std::runtime_error(why);}
bool waits(LockManager& lm,std::uint64_t tx,std::uint64_t on){auto s=lm.snapshot();for(const auto& w:s["waits"])if(w["tx_id"]==tx)for(const auto& b:w["blocked_by"])if(b==on)return true;return false;}
void domain(LockManager& lm,const std::string& name="range:t:pk",const std::string& table="table:t"){lm.register_resource("database-data");lm.register_resource(table,"database-data");lm.register_resource(name,table);}
void intent(LockManager& lm,std::uint64_t tx,bool write,const std::string& table="table:t"){lm.acquire_path(tx,table,write?Mode::IX:Mode::IS);}
void empty(LockManager& lm){auto s=lm.snapshot();need(s["locks"].empty()&&s["queues"].empty()&&s["waits"].empty(),"Range lifecycle leaked holders/queue/edges");}
void endpoints(){
    const auto low=std::numeric_limits<std::int64_t>::min(),high=std::numeric_limits<std::int64_t>::max();
    need(LockManager::range_empty({high,{},false,true}),"Exclusive MAX lower is empty");need(LockManager::range_empty({{},low,true,false}),"Exclusive MIN upper is empty");need(!LockManager::range_empty(point(low))&&!LockManager::range_empty(point(high)),"MIN/MAX point does not overflow");need(!LockManager::ranges_overlap({10,20,false,false},point(20)),"Right-open bound excludes20");need(LockManager::ranges_overlap({10,20,false,false},point(15)),"Empty table gap still covers15");
    std::mt19937 generator(1515);std::uniform_int_distribution<int> value(-10,10);for(unsigned trial=0;trial<3000;++trial){Range a{value(generator),value(generator),bool(generator()%2),bool(generator()%2)},b{value(generator),value(generator),bool(generator()%2),bool(generator()%2)};bool oracle=false;for(std::int64_t k=-12;k<=12;++k){auto contains=[&](const Range& r){return (k>*r.lower||(k==*r.lower&&r.lower_inclusive))&&(k<*r.upper||(k==*r.upper&&r.upper_inclusive));};oracle|=contains(a)&&contains(b);}need(LockManager::ranges_overlap(a,b)==oracle,"Independent finite integer set overlap oracle");}
}
void gap_and_hierarchy(){LockManager lm(2s);domain(lm);intent(lm,1,false);lm.acquire_range(1,"range:t:pk",{10,20,false,false},Mode::S);intent(lm,2,true);need(!lm.acquire_range(2,"range:t:pk",point(15),Mode::X,true),"Gap S blocks INSERT15");need(lm.acquire_range(2,"range:t:pk",point(20),Mode::X,true),"Gap S does not block right-open20");intent(lm,3,false);need(lm.acquire_range(3,"range:t:pk",point(15),Mode::S,true),"Shared range readers compatible");error("LOCK_HIERARCHY",[&]{lm.acquire_range(4,"range:t:pk",point(15),Mode::X,true);});error("ARGUMENT",[&]{lm.acquire(4,"range:t:pk",Mode::S,true);});need(!lm.acquire_path(5,"table:t",Mode::S,true),"Coarse tableS conflicts with recordIX");observations.push_back({{"kind","gap_and_actual_intentions"},{"snapshot",lm.snapshot()}});for(unsigned id=1;id<=5;++id)lm.release(id);empty(lm);}
void fifo(){LockManager lm(3s);domain(lm);for(auto tx:{1,2,3,4})intent(lm,tx,true);lm.acquire_range(1,"range:t:pk",{0,10,true,true},Mode::S);std::promise<void> let_writer;auto gate=let_writer.get_future().share();auto writer=std::async(std::launch::async,[&]{try{lm.acquire_range(2,"range:t:pk",point(5),Mode::X);if(gate.wait_for(2s)!=std::future_status::ready)throw DbError("TEST_TIMEOUT","Bounded writer gate");lm.release(2);return std::string("PASS");}catch(const DbError& e){lm.release(2);return e.code;}});until([&]{return waits(lm,2,1);},"Writer queue missing");auto reader=std::async(std::launch::async,[&]{try{lm.acquire_range(3,"range:t:pk",point(5),Mode::S);lm.release(3);return std::string("PASS");}catch(const DbError& e){lm.release(3);return e.code;}});until([&]{return waits(lm,3,2);},"Later reader did not wait for overlapping FIFO writer");need(lm.acquire_range(4,"range:t:pk",point(50),Mode::X,true),"Disjoint request bypasses non-overlapping queue");observations.push_back({{"kind","actual_fifo_predecessor_wait"},{"snapshot",lm.snapshot()}});lm.release(1);until([&]{auto s=lm.snapshot();for(const auto& l:s["locks"])if(l["tx_id"]==2&&l.contains("interval"))return true;return false;},"First writer did not acquire after reader release");need(reader.wait_for(0ms)!=std::future_status::ready,"Reader did not barge during writer");let_writer.set_value();need(writer.get()=="PASS"&&reader.get()=="PASS","FIFO waiter lifecycle");lm.release(4);empty(lm);}
void deadlock(){LockManager lm(3s);domain(lm);intent(lm,10,true);intent(lm,20,true);lm.acquire_range(10,"range:t:pk",point(1),Mode::X);lm.acquire_range(20,"range:t:pk",point(2),Mode::X);auto first=std::async(std::launch::async,[&]{try{lm.acquire_range(10,"range:t:pk",point(2),Mode::X);lm.release(10);return std::string("PASS");}catch(const DbError& e){lm.release(10);return e.code;}});until([&]{return waits(lm,10,20);},"Real range dependency missing");error("DEADLOCK",[&]{lm.acquire_range(20,"range:t:pk",point(1),Mode::X);});auto s=lm.snapshot();bool victim=false;for(const auto& e:s["events"])if(e["kind"]=="deadlock_cycle"){need(e["details"]["victim"]==20,"Deadlock greatest transaction victim");victim=true;}need(victim,"Real range deadlock event");observations.push_back({{"kind","actual_range_deadlock"},{"snapshot",s}});lm.release(20);need(first.get()=="PASS","Range deadlock survivor resumes");empty(lm);}
void timeout_rollback_and_commit(){LockManager lm(35ms);domain(lm);intent(lm,1,true);intent(lm,2,true);lm.acquire_range(1,"range:t:pk",point(7),Mode::X);error("LOCK_TIMEOUT",[&]{lm.acquire_range(2,"range:t:pk",point(7),Mode::S);});error("DEADLOCK",[&]{lm.prepare_commit(2);});lm.release(2);lm.release(1);empty(lm);intent(lm,3,true);lm.acquire_range(3,"range:t:pk",point(7),Mode::X);auto permit=lm.prepare_commit(3);lm.commit_succeeded(permit);error("NO_TRANSACTION",[&]{lm.acquire_range(3,"range:t:pk",point(8),Mode::X);});lm.release(3);empty(lm);}
void mixed_graph(){LockManager lm(3s);domain(lm);intent(lm,1,false);lm.acquire_range(1,"range:t:pk",point(1),Mode::S);lm.acquire_path(2,"table:t",Mode::S);intent(lm,2,true);auto coarse_wait=std::async(std::launch::async,[&]{try{intent(lm,1,true);lm.acquire_range(1,"range:t:pk",point(2),Mode::X);lm.release(1);return std::string("PASS");}catch(const DbError& e){lm.release(1);return e.code;}});until([&]{return waits(lm,1,2);},"Coarse table wait edge missing");error("DEADLOCK",[&]{lm.acquire_range(2,"range:t:pk",point(1),Mode::X);});auto s=lm.snapshot();bool found=false;for(const auto& event:s["events"])if(event["kind"]=="deadlock_cycle"){found=true;need(event["details"]["victim"]==2,"Mixed table/range cycle chooses greatest transaction");}need(found,"One graph detects a cycle spanning table intention and key range");observations.push_back({{"kind","mixed_table_range_deadlock"},{"snapshot",s}});lm.release(2);need(coarse_wait.get()=="PASS","Mixed coarse/range survivor resumes");empty(lm);}
void policies(){
    {LockManager lm(2s,DeadlockPolicy::WaitDie);domain(lm);intent(lm,1,true);intent(lm,2,true);lm.acquire_range(1,"range:t:pk",point(1),Mode::S);error("DEADLOCK",[&]{lm.acquire_range(2,"range:t:pk",point(1),Mode::X);});lm.release(2);lm.release(1);empty(lm);}
    {LockManager lm(2s,DeadlockPolicy::WoundWait);domain(lm);intent(lm,1,true);intent(lm,2,true);auto cancellation=lm.cancellation_token(2);lm.acquire_range(2,"range:t:pk",point(1),Mode::S);auto older=std::async(std::launch::async,[&]{try{lm.acquire_range(1,"range:t:pk",point(1),Mode::X);lm.release(1);return std::string("PASS");}catch(const DbError& e){lm.release(1);return e.code;}});until([&]{return cancellation->load();},"Range wound-wait did not cancel younger holder");error("DEADLOCK",[&]{lm.check_cancelled(2);});lm.release(2);need(older.get()=="PASS","Older wounded range requester resumes after real rollback");empty(lm);}
}
}
int main(){try{endpoints();gap_and_hierarchy();fifo();deadlock();timeout_rollback_and_commit();mixed_graph();policies();std::cout<<"OBSERVATIONS "<<observations.dump()<<"\nPASS native range lock "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL range after "<<checks<<": "<<e.what()<<"\n";return 1;}}
